import React from 'react';
import { Tabs, Tab } from 'carbon-components-react';
import { Home32, Bookmark32, Tag32 } from '@carbon/icons-react';

function IconOnlyTabsDefault() {
  return (
    <Tabs>
      <Tab renderIcon={Home32} iconDescription="Home" />
      <Tab renderIcon={Bookmark32} iconDescription="Bookmark" />
      <Tab renderIcon={Tag32} iconDescription="Tag" />
    </Tabs>
  );
}

function IconOnlyTabsLarge() {
  return (
    // Attempt to apply a `size="large"` prop to get 48px height
    <Tabs size="large">
      <Tab renderIcon={Home32} iconDescription="Home" />
      <Tab renderIcon={Bookmark32} iconDescription="Bookmark" />
      <Tab renderIcon={Tag32} iconDescription="Tag" />
    </Tabs>
  );
}

export default function App() {
  return (
    <div style={{ padding: 20 }}>
      <h2>Line – icon only (40px default)</h2>
      <IconOnlyTabsDefault />

      <h2>Line – icon only (48px large)</h2>
      <IconOnlyTabsLarge />

      <h2>Contained – icon only (40px default)</h2>
      {/* Just change `type` to get the contained style */}
      <Tabs type="container">
        <Tab renderIcon={Home32} iconDescription="Home" />
        <Tab renderIcon={Bookmark32} iconDescription="Bookmark" />
        <Tab renderIcon={Tag32} iconDescription="Tag" />
      </Tabs>

      <h2>Contained – icon only (48px large)</h2>
      <Tabs type="container" size="large">
        <Tab renderIcon={Home32} iconDescription="Home" />
        <Tab renderIcon={Bookmark32} iconDescription="Bookmark" />
        <Tab renderIcon={Tag32} iconDescription="Tag" />
      </Tabs>
    </div>
  );
}
